(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiReplays=api;})(typeof window!=='undefined'?window:globalThis,function(){
 'use strict';
 const version=1,limit=20,favoriteLimit=50,maxBytes=524288,modes=['classic','endless','special','condition','one-shot','promotion-boss','promotion-mission','friend','online','friend-cpu'];
 const round=n=>Math.round(n*100)/100;
 const point=(b,center,radius)=>[round(Math.max(-5000,Math.min(5000,200+(b.position.x-center.x)*184/radius))),round(Math.max(-5000,Math.min(5000,200+(b.position.y-center.y)*184/radius))),round(b.angle),b.gameData.isOut?1:0,round(b.circleRadius*184/radius)];
 function piece(b,side,center,radius){const d=b.gameData,factor=184/radius;return{char:d.char,attr:d.attr,jis:d.jis,level:d.level||1,cpuControlled:d.cpuControlled===true,ruby:d.ruby||'',equippedReadings:(d.equippedReadings||[]).slice(),side,radius:round(b.circleRadius*factor),scale:round((b.traitScale||1)*factor),outline:b.traitOutline?.map(v=>({x:round(v.x*factor),y:round(v.y*factor)}))||null};}
 const snapshot=(bodies,center,radius,ratio=1,time=0)=>[Math.round(time),round(ratio),bodies.map(b=>point(b,center,radius))];
 function create(meta,pieces,initial){return{version,...meta,pieces,initial,turns:[],final:initial,winner:null,reason:'',complete:false};}
 function finish(record,winner,reason,final){if(record.complete)return record;record.winner=winner;record.reason=reason||'全滅';record.final=final;record.complete=true;return record;}
 function summary(r){return{id:r.id,createdAt:r.createdAt,mode:r.mode,label:r.label,names:r.names,side:r.side,winner:r.winner,reason:r.reason,turns:r.turns.length,chars:r.pieces.filter(p=>p.side===r.side).map(p=>p.char),opponents:r.pieces.filter(p=>p.side!==r.side).map(p=>p.char),duration:duration(r)};}
 const duration=r=>r.turns.reduce((n,t)=>n+t.duration,0);
 function frameAt(turn,time){const frames=turn.frames;let right=frames.findIndex(f=>f[0]>time);if(right<0)return frames.at(-1);if(right===0)return frames[0];const left=frames[right-1],next=frames[right],mix=(time-left[0])/(next[0]-left[0]||1);return[time,left[1],left[2].map((p,n)=>p.map((v,k)=>k===3?v:round(v+(next[2][n][k]-v)*mix)))];}
 function at(r,time){time=Math.max(0,Math.min(duration(r),time));let start=0;for(let n=0;n<r.turns.length;n++){const turn=r.turns[n];if(time<start+turn.duration)return{frame:frameAt(turn,time-start),turn,index:n,local:time-start};start+=turn.duration;}return{frame:r.final,turn:r.turns.at(-1)||null,index:Math.max(0,r.turns.length-1),local:r.turns.at(-1)?.duration||0};}
 function offset(r,index){return r.turns.slice(0,Math.max(0,index)).reduce((n,t)=>n+t.duration,0);}
 function valid(r,known=()=>true){
  const number=(v,min,max)=>Number.isFinite(v)&&v>=min&&v<=max,int=(v,min,max)=>Number.isInteger(v)&&number(v,min,max),text=(v,max)=>typeof v==='string'&&v.length<=max&&!/[\x00-\x1f<>]/.test(v),side=v=>v===0||v===1;
  if(!r||r.version!==version||!text(r.id,100)||!/^[A-Za-z0-9_-]+$/.test(r.id)||!number(r.createdAt,1,1e15)||!modes.includes(r.mode)||!text(r.label,80)||!Array.isArray(r.names)||r.names.length!==2||!r.names.every(n=>text(n,40))||!side(r.side)||![0,1,null].includes(r.winner)||!text(r.reason,80)||typeof r.complete!=='boolean')return false;
  if(!Array.isArray(r.pieces)||r.pieces.length<4||r.pieces.length>6||r.pieces.some(p=>!p||!known(p.char)||typeof p.char!=='string'||Array.from(p.char).length!==1||!['wood','fire','earth','metal','water'].includes(p.attr)||!int(p.jis,1,5)||!int(p.level,1,p.side===1&&['classic','endless'].includes(r.mode)?150:100)||(p.cpuControlled!==undefined&&typeof p.cpuControlled!=='boolean')||!text(p.ruby,40)||!Array.isArray(p.equippedReadings)||p.equippedReadings.length>200||!p.equippedReadings.every(v=>text(v,40))||!side(p.side)||!number(p.radius,1,250)||!number(p.scale,.01,10)||p.outline!==null&&(!Array.isArray(p.outline)||p.outline.length<3||p.outline.length>20||p.outline.some(v=>!number(v.x,-250,250)||!number(v.y,-250,250)))))return false;
  const frame=f=>Array.isArray(f)&&f.length===3&&int(f[0],0,6000)&&number(f[1],.5,1.01)&&Array.isArray(f[2])&&f[2].length===r.pieces.length&&f[2].every(p=>Array.isArray(p)&&p.length===5&&number(p[0],-5000,5000)&&number(p[1],-5000,5000)&&number(p[2],-1e6,1e6)&&(p[3]===0||p[3]===1)&&number(p[4],1,250));
  if(!frame(r.initial)||!frame(r.final)||!Array.isArray(r.turns)||r.turns.length>36)return false;
  return r.turns.every(t=>t&&side(t.side)&&int(t.key,0,r.pieces.length-1)&&r.pieces[t.key].side===t.side&&number(t.spin,-3,3)&&int(t.duration,1,6000)&&Array.isArray(t.frames)&&t.frames.length>=2&&t.frames.length<=100&&t.frames.every((f,i)=>frame(f)&&f[0]<=t.duration&&(!i||f[0]>=t.frames[i-1][0]))&&t.frames[0][0]===0&&t.frames.at(-1)[0]===t.duration&&Array.isArray(t.events)&&t.events.length<=120&&t.events.every(e=>e&&int(e.t,0,t.duration)&&int(e.key,0,r.pieces.length-1)&&text(e.name,40)&&/^#[0-9a-fA-F]{3,8}$/.test(e.color)));
 }
 return{version,limit,favoriteLimit,maxBytes,modes,round,point,piece,snapshot,create,finish,summary,duration,at,offset,valid};
});
